package org.eclipse.wildwebdeveloper.eslint;

import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;

import org.eclipse.lsp4j.ConfigurationItem;
import org.eclipse.lsp4j.ConfigurationParams;
import org.junit.Test;

public class ESLintClientImplTest {
    @Test
    public void configuration_withInvalidScopeUri_shouldNotThrowNPE() {
        ESLintClientImpl client = new ESLintClientImpl();
        ConfigurationItem configItem = new ConfigurationItem();
        configItem.setScopeUri("not a valid uri:::");
        ConfigurationParams params = new ConfigurationParams(Collections.singletonList(configItem));
        CompletableFuture<List<Object>> result = client.configuration(params);
        try {
            result.get();
        } catch (InterruptedException | java.util.concurrent.ExecutionException e) {
            if (e.getCause() instanceof NullPointerException) {
                throw new AssertionError("Bug confirmed: NullPointerException thrown when URI parsing fails", e);
            }
            throw new AssertionError("Unexpected exception", e);
        }
    }
}

package org.eclipse.wildwebdeveloper.eslint;

import java.io.File;
import java.net.URI;
import java.net.URISyntaxException;

/**
 * Standalone test demonstrating the null scopeUri bug in ESLintClientImpl.
 * 
 * The bug: when configurationItem.getScopeUri() returns null (as LSP4J API allows),
 * new URI(null) throws NullPointerException, not URISyntaxException, so the catch
 * block does not catch it, resulting in an unhandled exception.
 * 
 * Run with: java org.eclipse.wildwebdeveloper.eslint.ESLintClientImplNullScopeUriTest
 * Exit code 0 = tests pass (no bug)
 * Exit code 1 = tests fail (bug present)
 */
public class ESLintClientImplNullScopeUriTest {

	/**
	 * Replicates the exact code pattern from ESLintClientImpl.configuration()
	 * line 46: new File(new URI(configurationItem.getScopeUri())).getParentFile()
	 * line 52: catch (URISyntaxException e)
	 * 
	 * When scopeUri is null, new URI(null) throws NullPointerException,
	 * which is NOT caught by the URISyntaxException catch block.
	 * 
	 * @return true if bug is present (NPE thrown), false if handled gracefully
	 */
	public static boolean testNullScopeUriThrowsUnhandledNPE() {
		String scopeUri = null; // simulates configurationItem.getScopeUri() returning null

		try {
			File highestPackageJsonDir = null;
			try {
				highestPackageJsonDir = new File(new URI(scopeUri)).getParentFile();
				File parentFile = highestPackageJsonDir;
				while (parentFile != null) {
					if (new File(parentFile, "package.json").exists()) highestPackageJsonDir = parentFile;
					parentFile = parentFile.getParentFile();
				}
			} catch (URISyntaxException e) {
				// only catches URISyntaxException, not NullPointerException
			}
			// If we reach here, the code handled it (or highestPackageJsonDir is null)
			return highestPackageJsonDir == null;
		} catch (NullPointerException e) {
			// Bug present: NPE escaped the catch block
			return true; // bug is present
		}
	}

	/**
	 * Verifies that new URI(null) throws NullPointerException, not URISyntaxException.
	 */
	public static boolean testURINullThrowsNPE() {
		try {
			new URI((String) null);
			return true; // bug: should have thrown
		} catch (NullPointerException e) {
			return false; // expected: NPE is thrown, not URISyntaxException
		} catch (URISyntaxException e) {
			return true; // bug: wrong exception type
		}
	}

	public static void main(String[] args) {
		int failures = 0;

		// Test 1: verify new URI(null) throws NPE (root cause)
		if (testURINullThrowsNPE()) {
			System.out.println("FAIL: new URI(null) did not throw NullPointerException");
			failures++;
		} else {
			System.out.println("PASS: new URI(null) throws NullPointerException as expected");
		}

		// Test 2: the ESLintClientImpl bug - NPE escapes the catch block
		if (testNullScopeUriThrowsUnhandledNPE()) {
			System.out.println("FAIL: null scopeUri causes unhandled NullPointerException (BUG CONFIRMED)");
			failures++;
		} else {
			System.out.println("PASS: null scopeUri is handled gracefully");
		}

		if (failures > 0) {
			System.out.println("\n" + failures + " test(s) FAILED - bug is present");
			System.exit(1);
		} else {
			System.out.println("\nAll tests PASSED - no bug detected");
			System.exit(0);
		}
	}
}

