/**
 * Regression test for ESLintClientImpl.configuration() demonstrating the bug where
 * highestPackageJsonDir can be null when URISyntaxException is caught, causing
 * NullPointerException on toURI() and getAbsolutePath().
 * 
 * The OLD code used NodeJSManager.getNodeJsLocation().getAbsolutePath() which
 * always returned a valid path. The NEW code uses highestPackageJsonDir which
 * can be null if URISyntaxException is caught (invalid scope URI).
 * 
 * This test replicates the exact logic from ESLintClientImpl.configuration()
 * and asserts that highestPackageJsonDir should NOT be null (correct behavior).
 * It FAILS on the buggy code because highestPackageJsonDir is null.
 */
public class ESLintClientImplConfigurationNullDirTest {

	/**
	 * Regression test: ESLintClientImpl.configuration() should NOT leave 
	 * highestPackageJsonDir as null when the scope URI is invalid.
	 * 
	 * BUG: ESLintClientImpl sets highestPackageJsonDir = null initially.
	 * If the scope URI is invalid, URISyntaxException is caught and highestPackageJsonDir
	 * remains null. Then the code calls highestPackageJsonDir.toURI() which throws NPE.
	 * 
	 * FIX: The code should handle the null case gracefully, e.g. by providing a fallback
	 * like the OLD code did with NodeJSManager.getNodeJsLocation().
	 * 
	 * This test REPLICATES the exact logic from ESLintClientImpl.configuration() and asserts
	 * that highestPackageJsonDir should NOT be null (or should be handled gracefully).
	 * It FAILS on the buggy code because NPE is thrown.
	 */
	public static void testShouldNotThrowNPEOnInvalidScopeUri() throws Exception {
		// An invalid URI that causes URISyntaxException
		String invalidScopeUri = "://invalid uri with spaces and colons";

		// This replicates the EXACT logic from ESLintClientImpl.configuration():
		File highestPackageJsonDir = null;
		try {
			highestPackageJsonDir = new File(new URI(invalidScopeUri)).getParentFile();
			File parentFile = highestPackageJsonDir;
			while (parentFile != null) {
				if (new File(parentFile, "package.json").exists()) highestPackageJsonDir = parentFile;
				parentFile = parentFile.getParentFile();
			}
		} catch (URISyntaxException e) {
			// In ESLintClientImpl: "// shouldn't happen else what to do here?"
			// The exception is caught and highestPackageJsonDir remains null
		}

		// highestPackageJsonDir is null because URISyntaxException was caught
		System.out.println("highestPackageJsonDir after invalid URI = " + highestPackageJsonDir);

		// CORRECT behavior: highestPackageJsonDir should NOT be null
		// The code should have a fallback (like the old NodeJSManager.getNodeJsLocation())
		if (highestPackageJsonDir == null) {
			throw new AssertionError("BUG: highestPackageJsonDir is null after URISyntaxException caught - " +
				"ESLintClientImpl.configuration() will throw NullPointerException on line 55/63. " +
				"The code should provide a fallback like the old NodeJSManager.getNodeJsLocation() did.");
		}

		// If we get here, highestPackageJsonDir is NOT null - the bug is fixed
		Map<String, Object> config = new HashMap<>(6, 1.f);
		config.put("workspaceFolder", Collections.singletonMap("uri", highestPackageJsonDir.toURI().toString()));
		config.put("nodePath", highestPackageJsonDir.getAbsolutePath());

		System.out.println("PASS: testShouldNotThrowNPEOnInvalidScopeUri - highestPackageJsonDir handled correctly");
	}

	/**
	 * Test that when there's a file in a subdirectory with no package.json,
	 * the code still works (highestPackageJsonDir is the file's parent, not null).
	 * This is the normal case where ESLintClientImpl does NOT throw NPE.
	 */
	public static void testNoPackageJsonButFileHasParent() throws Exception {
		Path tempDir = Files.createTempDirectory("eslint-test");
		Path testFile = Files.createFile(tempDir.resolve("test.js"));

		// Simulate ESLintClientImpl logic with this file's scope URI
		String scopeUri = "file://" + testFile.toAbsolutePath();

		File highestPackageJsonDir = null;
		try {
			highestPackageJsonDir = new File(new URI(scopeUri)).getParentFile();
			File parentFile = highestPackageJsonDir;
			while (parentFile != null) {
				if (new File(parentFile, "package.json").exists()) highestPackageJsonDir = parentFile;
				parentFile = parentFile.getParentFile();
			}
		} catch (URISyntaxException e) {
		}

		// highestPackageJsonDir is the tempDir (the file's parent), NOT null
		// because even without package.json, it starts as the file's parent
		if (highestPackageJsonDir == null) {
			throw new AssertionError("highestPackageJsonDir should be tempDir, not null");
		}

		// This works fine - no NPE
		Map<String, Object> config = new HashMap<>();
		config.put("workspaceFolder", Collections.singletonMap("uri", highestPackageJsonDir.toURI().toString()));
		config.put("nodePath", highestPackageJsonDir.getAbsolutePath());

		// Clean up
		Files.walk(tempDir).sorted((a, b) -> b.compareTo(a)).map(Path::toFile).forEach(File::delete);

		System.out.println("PASS: testNoPackageJsonButFileHasParent - works when file has a parent directory");
	}

	/**
	 * Test that the code works correctly when a package.json exists in the directory.
	 */
	public static void testConfigurationWorksWithPackageJson() throws Exception {
		Path tempDir = Files.createTempDirectory("eslint-test");
		Path testFile = Files.createFile(tempDir.resolve("test.js"));

		// Create a package.json in the temp dir
		try (FileWriter fw = new FileWriter(tempDir.resolve("package.json").toFile())) {
			fw.write("{}");
		}

		File highestPackageJsonDir = null;
		try {
			highestPackageJsonDir = new File(new URI("file://" + testFile.toAbsolutePath())).getParentFile();
			File parentFile = highestPackageJsonDir;
			while (parentFile != null) {
				if (new File(parentFile, "package.json").exists()) highestPackageJsonDir = parentFile;
				parentFile = parentFile.getParentFile();
			}
		} catch (URISyntaxException e) {
		}

		// highestPackageJsonDir should NOT be null when package.json exists
		if (highestPackageJsonDir == null) {
			throw new AssertionError("highestPackageJsonDir should not be null when package.json exists");
		}

		// This should work since highestPackageJsonDir is not null
		Map<String, Object> config = new HashMap<>();
		config.put("workspaceFolder", Collections.singletonMap("uri", highestPackageJsonDir.toURI().toString()));
		config.put("nodePath", highestPackageJsonDir.getAbsolutePath());

		assertEquals(tempDir.toAbsolutePath().toString(), highestPackageJsonDir.getAbsolutePath());

		// Clean up
		Files.walk(tempDir).sorted((a, b) -> b.compareTo(a)).map(Path::toFile).forEach(File::delete);

		System.out.println("PASS: testConfigurationWorksWithPackageJson - works correctly when package.json exists");
	}

	/**
	 * Test that the code works when package.json exists in a parent directory.
	 */
	public static void testConfigurationWorksWithPackageJsonInParent() throws Exception {
		Path tempDir = Files.createTempDirectory("eslint-test");

		// Create subdirectory structure: tempDir/package.json and tempDir/sub/sub2/test.js
		try (FileWriter fw = new FileWriter(tempDir.resolve("package.json").toFile())) {
			fw.write("{}");
		}
		Path subDir = Files.createDirectories(tempDir.resolve("sub").resolve("sub2"));
		Path deepFile = Files.createFile(subDir.resolve("test.js"));

		File highestPackageJsonDir = null;
		try {
			highestPackageJsonDir = new File(new URI("file://" + deepFile.toAbsolutePath())).getParentFile();
			File parentFile = highestPackageJsonDir;
			while (parentFile != null) {
				if (new File(parentFile, "package.json").exists()) highestPackageJsonDir = parentFile;
				parentFile = parentFile.getParentFile();
			}
		} catch (URISyntaxException e) {
		}

		// highestPackageJsonDir should be the tempDir (where package.json is)
		if (highestPackageJsonDir == null) {
			throw new AssertionError("highestPackageJsonDir should not be null when parent has package.json");
		}

		assertEquals(tempDir.toAbsolutePath().toString(), highestPackageJsonDir.getAbsolutePath());

		// Clean up
		Files.walk(tempDir).sorted((a, b) -> b.compareTo(a)).map(Path::toFile).forEach(File::delete);

		System.out.println("PASS: testConfigurationWorksWithPackageJsonInParent");
	}

	private static void assertEquals(String expected, String actual) {
		if (!expected.equals(actual)) {
			throw new AssertionError("Expected: " + expected + " but was: " + actual);
		}
	}

	public static void main(String[] args) throws Exception {
		System.out.println("=== ESLintClientImplConfigurationNullDirTest ===\n");

		int passed = 0;
		int failed = 0;

		try {
			testShouldNotThrowNPEOnInvalidScopeUri();
			passed++;
		} catch (AssertionError e) {
			System.out.println("FAIL: testShouldNotThrowNPEOnInvalidScopeUri - " + e.getMessage());
			failed++;
		} catch (Exception e) {
			System.out.println("ERROR: testShouldNotThrowNPEOnInvalidScopeUri - " + e);
			failed++;
		}

		try {
			testNoPackageJsonButFileHasParent();
			passed++;
		} catch (Exception e) {
			System.out.println("FAIL: testNoPackageJsonButFileHasParent - " + e.getMessage());
			failed++;
		}

		try {
			testConfigurationWorksWithPackageJson();
			passed++;
		} catch (Exception e) {
			System.out.println("FAIL: testConfigurationWorksWithPackageJson - " + e.getMessage());
			failed++;
		}

		try {
			testConfigurationWorksWithPackageJsonInParent();
			passed++;
		} catch (Exception e) {
			System.out.println("FAIL: testConfigurationWorksWithPackageJsonInParent - " + e.getMessage());
			failed++;
		}

		System.out.println("\n=== Results: " + passed + " passed, " + failed + " failed ===");
		System.exit(failed > 0 ? 1 : 0);
	}
}

package org.eclipse.wildwebdeveloper.eslint;

import static org.junit.Assert.*;

import java.io.File;
import java.net.URI;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Regression test for the bug in ESLintClientImpl.configuration().
 * 
 * The problematic code (line 46 in ESLintClientImpl.java):
 *   highestPackageJsonDir = new File(new URI(configurationItem.getScopeUri())).getParentFile();
 * 
 * This assumes scopeUri is a file URI pointing to a FILE. But in LSP, scopeUri can be a
 * directory URI (e.g., workspace root). When it's a directory, getParentFile() goes one
 * level UP unnecessarily, starting the package.json search from the wrong location and
 * skipping the directory that actually contains package.json.
 */
public class ESLintClientImplDirectoryScopeTest {

	@Rule
	public TemporaryFolder tempFolder = new TemporaryFolder();

	/**
	 * Simulates the exact logic from ESLintClientImpl.configuration() line 46:
	 *   File highestPackageJsonDir = new File(new URI(scopeUri)).getParentFile();
	 * 
	 * When scopeUri is a DIRECTORY containing package.json, getParentFile() returns
	 * the PARENT of that directory, so the package.json in the directory itself is skipped.
	 */
	@Test
	public void getParentFile_skipsDirectoryContainingPackageJson() throws Exception {
		// Set up: create a workspace directory with package.json
		File workspace = tempFolder.newFolder("workspace");
		File packageJson = new File(workspace, "package.json");
		packageJson.createNewFile();

		// scopeUri is a DIRECTORY URI (the workspace root)
		String scopeUri = workspace.toURI().toString();

		// This is the EXACT buggy logic from ESLintClientImpl.java line 46:
		// highestPackageJsonDir = new File(new URI(configurationItem.getScopeUri())).getParentFile();
		File startDir = new File(new URI(scopeUri)).getParentFile();

		// BUG: startDir is the PARENT of workspace, not workspace itself.
		// So searching for package.json starting from startDir skips workspace/package.json
		File found = null;
		File current = startDir;
		while (current != null) {
			if (new File(current, "package.json").exists()) {
				found = current;
				break;
			}
			current = current.getParentFile();
		}

		// The correct result should be that 'workspace' itself contains package.json
		// But with the bug, startDir is workspace.getParentFile(), which is the grandparent
		// So the while loop starts from the parent of workspace, not workspace itself

		// This assertion demonstrates the bug:
		// - If package.json exists in workspace.getParentFile(), found might not be workspace
		// - If package.json exists ONLY in workspace, found will be null or wrong
		assertNotNull("package.json should be found when scopeUri is a directory containing it", found);
		assertEquals("The found directory should be the workspace directory itself which contains package.json. " +
			"Bug causes search to start from parent of workspace instead, " +
			"skipping the directory that actually contains package.json. " +
			"scopeUri=" + scopeUri + ", startDir=" + startDir + ", found=" + found,
			workspace.getAbsolutePath(), found.getAbsolutePath());
	}

	/**
	 * When scopeUri points to a FILE, getParentFile() correctly returns the
	 * containing directory. This test shows the case that works correctly.
	 */
	@Test
	public void getParentFile_correctForFileScopeUri() throws Exception {
		// Set up: workspace/package.json and workspace/src/index.js
		File workspace = tempFolder.newFolder("workspace");
		new File(workspace, "package.json").createNewFile();
		File srcDir = new File(workspace, "src");
		srcDir.mkdirs();
		File indexFile = new File(srcDir, "index.js");
		indexFile.createNewFile();

		// scopeUri points to a FILE (index.js)
		String scopeUri = indexFile.toURI().toString();

		// The same logic - but for a FILE URI, getParentFile() gives the containing dir
		File startDir = new File(new URI(scopeUri)).getParentFile();

		// startDir should be srcDir (the directory containing index.js)
		assertEquals("For a file URI, getParentFile() should return the containing directory",
			srcDir.getAbsolutePath(), startDir.getAbsolutePath());

		// The while loop then walks up and should find workspace/package.json
		File found = null;
		File current = startDir;
		while (current != null) {
			if (new File(current, "package.json").exists()) {
				found = current;
				break;
			}
			current = current.getParentFile();
		}

		assertEquals("package.json should be found when walking up from a file's parent directory",
			workspace.getAbsolutePath(), found.getAbsolutePath());
	}
}

